def fold(cells):
    """cells: dict (row,col)->label, row 0 at top. Printed side out. Returns label->outward normal or None if not a cube net."""
    start=next(iter(cells)); F={start:((1,0,0),(0,1,0),(0,0,1))}; st=[start]
    neg=lambda v: tuple(-a for a in v)
    while st:
        r,c=st.pop(); e,n,z=F[(r,c)]
        for nb,fr in (((r,c+1),(neg(z),n,e)),((r,c-1),(z,n,neg(e))),((r-1,c),(e,neg(z),n)),((r+1,c),(e,z,neg(n)))):
            if nb in cells and nb not in F: F[nb]=fr; st.append(nb)
    if len(F)!=len(cells): return None
    N={cells[k]:f[2] for k,f in F.items()}
    if len(set(N.values()))!=6: return None
    return N

